<?php if($comm): ?>
<section class="comm-card"><h2>Subscription and recharge requests</h2><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Request</th><th>Amount / credits</th><th>Status</th><th>Payment</th></tr></thead><tbody><?php foreach($comm['requests'] as $r):if($r['module_key']!==$channel)continue; ?><tr><td>#<?= (int)$r['id']; ?> · <?= $h($r['purpose']); ?><br><span class="muted"><?= $h($r['billing_period']??'Credits'); ?><?php if(!empty($r['automation_plan_key'])): ?> · <?= $h($comm['automation']['plans'][$r['automation_plan_key']]['name']??$r['automation_plan_key']); ?><?php endif; ?></span></td><td><?= $money($r['amount_kobo']); ?><?= !empty($r['tax_kobo'])?' <span class="muted">incl. '.$money($r['tax_kobo']).' VAT</span>':''; ?><?= $r['credit_units']?' / '.number_format($r['credit_units']).' credits':''; ?></td><td><span class="comm-badge <?= $r['status']==='approved'?'ok':'off'; ?>"><?= $h(str_replace('_',' ',$r['status'])); ?></span></td><td><?php if($r['payment_reference']): ?><span class="mini"><?= $h($r['payment_reference']); ?></span><?php if($r['status']==='awaiting_payment' && parse_url($r['checkout_url']??'',PHP_URL_SCHEME)==='https'): ?><a class="btn secondary" href="<?= $h($r['checkout_url']); ?>">Continue payment</a><?php endif; ?><?php if($r['status']==='awaiting_payment'): $form('verify_purchase',$channel,array('reference'=>$r['payment_reference'])); ?><button class="btn secondary">Check payment</button><?= form_close(); ?><?php endif; ?><?php else: ?>Sales will contact you<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>

<?php endif; ?>

<?php $receiptDocs=array_filter($comm['review']['documents']??array(),function($d){return $d['kind']==='receipt';});if($receiptDocs): ?><section class="comm-card"><h2>Your uploaded receipts</h2><?php foreach($receiptDocs as $doc): ?><p>Request #<?= (int)$doc['reference_id']; ?> · <a href="<?= base_url('communications/document/'.(int)$doc['id']); ?>"><?= $h($doc['filename']); ?></a></p><?php endforeach; ?></section><?php endif; ?>
